import {REFERENCE_STYLE} from './reference-style.js';
// Both observer and unobstructed vessel views are generated by this fragment program.
export const vertex = `
precision highp float;
attribute vec3 position;
attribute vec2 uv;
varying vec2 vUv;
void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }
`;

export const raytrace = `
precision highp float;
varying vec2 vUv;
uniform vec2 uResolution;
uniform vec3 uCamera, uRight, uUp, uForward;
uniform float uFov, uCenter, uTime, uStep, uInner, uOuter;
uniform float uTemperature, uLuminosity, uOpacity, uTurbulence, uRotation;
uniform float uDoppler, uRedshift, uStarDensity, uGalaxy;
uniform float uHoleScale,uLensing,uDiskThickness,uStarBrightness,uPhotonRing,uShipView;
uniform int uMaxSteps, uDebug;
const float PI = 3.141592653589793;

float hash(vec3 p){ p = fract(p * .1031); p += dot(p,p.yzx+33.33); return fract((p.x+p.y)*p.z); }
float hash2(vec2 p){ return hash(vec3(p,17.13)); }
float noise3(vec3 p){
  vec3 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
  return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),
             mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);
}
float fbm(vec3 p){ float s=0.0,a=.5; for(int i=0;i<4;i++){s+=a*noise3(p);p=p*2.03+vec3(12.1,4.7,8.2);a*=.5;}return s;}
float fbm3(vec3 p){ float s=0.0,a=.5; for(int i=0;i<3;i++){s+=a*noise3(p);p=p*2.03+vec3(12.1,4.7,8.2);a*=.5;}return s;}

vec3 stars(vec3 d){
  float lon=atan(d.z,d.x)/(2.0*PI)+.5;
  float lat=asin(clamp(d.y,-1.0,1.0))/PI+.5;
  vec3 light=vec3(0.0);
  float pixel=1.0/uResolution.y;
  for(int layer=0;layer<3;layer++){
    float scale=240.0+float(layer)*143.0;
    vec2 cell=vec2(lon*2.0,lat)*scale;
    vec2 id=floor(cell);
    vec2 delta=fract(cell)-vec2(.23+.54*hash2(id+float(layer)*89.0),.23+.54*hash2(id+41.0+float(layer)*73.0));
    // Angular metric compensates longitude compression near the poles.
    delta.x*=max(cos((lat-.5)*PI),.08);
    float h=hash2(id+float(layer)*217.0+77.0);
    float present=step(1.0-min(.20,uStarDensity*.045),h);
    float radius=.018+.045*hash2(id+37.0);
    float aa=max(.012,pixel*scale*.25);
    float profile=exp(-dot(delta,delta)/(radius*radius+aa*aa));
    float energy=radius*radius/(radius*radius+aa*aa);
    vec3 tint=mix(vec3(.63,.77,1.0),vec3(1.0,.79,.51),hash2(id+91.0));
    light+=tint*profile*energy*present*(.6+pow(hash2(id+3.0),7.0)*7.0);
  }
  return light;
}
vec3 sky(vec3 d){
  vec3 q=vec3(.89*d.x+.35*d.y+.29*d.z,-.43*d.x+.71*d.y+.55*d.z,-.02*d.x-.61*d.y+.79*d.z);
  float cloud=fbm3(q*7.0+3.0);
  float band=exp(-pow(abs(q.y+.09*(cloud-.5))/.17,2.0));
  float dust=noise3(q*31.0+7.0);
  vec3 nebula=mix(vec3(.035,.055,.054),vec3(.12,.105,.078),cloud);
  vec3 gal=nebula*band*(.25+cloud*1.5)*(.3+dust)*uGalaxy;
  gal*=1.0-.74*smoothstep(.43,.68,noise3(q*45.0))*exp(-abs(q.y)/.05);
  return vec3(.0012,.0019,.0024)+gal+stars(d)*uStarBrightness;
}

// u = rs/r, phi is angle within the ray's fixed orbital plane, rs = 1.
// Exact Schwarzschild null orbit equation: u'' = -u + 3u^2/2.
vec2 derivative(vec2 s){return vec2(s.y,-s.x+1.5*uLensing*s.x*s.x);}
vec2 rk4(vec2 s,float h){
  vec2 a=derivative(s),b=derivative(s+a*h*.5),c=derivative(s+b*h*.5),d=derivative(s+c*h);
  return s+h*(a+2.0*b+2.0*c+d)/6.0;
}
vec3 thermal(float k){
  float t=clamp(k/100.0,10.0,400.0);
  float r=t<=66.0?1.0:clamp(1.292936*pow(t-60.0,-.133205),0.0,1.0);
  float g=t<=66.0?clamp(.390082*log(t)-.631841,0.0,1.0):clamp(1.129891*pow(t-60.0,-.075515),0.0,1.0);
  float b=t>=66.0?1.0:(t<=19.0?0.0:clamp(.543207*log(t-10.0)-1.196254,0.0,1.0));
  return pow(vec3(r,g,b),vec3(2.2));
}
// Every material feature uses the same angular displacement at every radius.
// Keeping the noise fixed in this rotating frame prevents differential drift.
float diskPhase(float angle){return angle-uTime*uRotation*.32;}
float ridged(float x){return pow(1.0-abs(2.0*clamp(x,0.0,1.0)-1.0),3.0);}

// Adapted from the supplied Blender disk. The angular coordinate supplies a
// rigid bulk rotation, while logarithmic-spiral domain warps create stretched
// vortices, torn filaments and non-periodic radial structure. No concentric
// sine bands are used.
float referenceNoise(vec3 p){
  float result=0.0,weight=1.0,total=0.0;
  for(int n=0;n<3;n++){result+=noise3(p)*weight;total+=weight;p=p*2.0+vec3(4.7,12.1,8.2);weight*=${REFERENCE_STYLE.roughness.toFixed(6)};}
  return result/total;
}
float turbulentDisk(float r,float phase){
  if(uTurbulence<.0005)return 1.0;
  float radius=max(r/uInner,.075);
  float radial=log(radius);
  float spiral=phase+radial*${Math.abs(REFERENCE_STYLE.shearExponent).toFixed(2)}+.28*sin(radial*3.1);

  // Large eddies are sampled on a deforming annular cylinder. Their coordinates
  // are stretched along the spiral direction instead of repeated in radius.
  vec2 orbit=vec2(cos(spiral),sin(spiral));
  vec3 broadQ=vec3(orbit*(1.85+.42*radial),radial*2.15+1.8);
  float broad=fbm3(broadQ*.78+vec3(5.1,8.7,3.4));
  float warp=(broad-.44)*2.6;
  vec2 midOrbit=vec2(cos(spiral+warp*.23),sin(spiral+warp*.23));
  vec3 midQ=vec3(midOrbit*(4.2+.72*radial),radial*4.5+broad*2.7);
  float middle=noise3(midQ+vec3(1.7,5.2,8.1));
  vec2 fineOrbit=vec2(cos(spiral+warp*.52+middle*.34),sin(spiral+warp*.52+middle*.34));
  vec3 fineQ=vec3(fineOrbit*(9.2+1.25*radial),radial*7.4+middle*3.2);
  float fine=noise3(fineQ+vec3(9.3,2.2,4.6));

  float cloud=smoothstep(.25,.74,broad*.68+middle*.22+fine*.10);
  float fibers=ridged(fine*.76+middle*.24);
  float lanes=smoothstep(.20,.82,middle*.56+fine*.32+broad*.12);
  float knots=.78+.42*smoothstep(.40,.83,broad+.12*middle);
  float density=(.10+1.26*cloud)*(.50+.82*fibers)*(.72+.42*lanes)*knots;

  // A weak inner hot sheet survives between the torn material and prevents the
  // disk from breaking into isolated blobs at grazing angles.
  density+=.035*exp(-pow(radial*.58,2.0))*(.55+.45*middle);
  return max(.025,density);
}
vec4 disk(vec3 p,vec3 backward,float observerF,out float g,out float grav,out float tempSeen,out float beam){
  float r=length(p);
  float angle=atan(p.z,p.x);
  float phase=diskPhase(angle);
  float texture=mix(1.0,turbulentDisk(r,phase),clamp(uTurbulence,0.0,1.45));
  float f=1.0-1.0/r;
  float beta=sqrt(.5/max(r-1.0,.51));
  vec3 orbital=normalize(vec3(-p.z,0.0,p.x));
  vec3 er=p/r;
  // Convert coordinate tangent to the local static observer's orthonormal frame.
  vec3 local=normalize(backward+er*dot(backward,er)*(inversesqrt(f)-1.0));
  float doppler=sqrt(1.0-beta*beta)/(1.0+beta*dot(orbital,local));
  grav=pow(sqrt(f/observerF),uRedshift);beam=pow(doppler,uDoppler);g=grav*beam;
  float taper=smoothstep(uInner,uInner+.45,r)*(1.0-smoothstep(uOuter*.76,uOuter,r));
  float emissivity=pow(uInner/r,2.2)*taper*texture;
  float temp=uTemperature*pow(uInner/r,.72)*(.91+.18*smoothstep(.35,1.65,texture));
  tempSeen=temp*g;
  vec3 color=thermal(temp*g)*uLuminosity*emissivity*pow(g,3.0);
  vec3 warm=vec3(${REFERENCE_STYLE.warmEmission.map(v=>v.toFixed(6)).join(',')});
  color*=mix(warm,vec3(1.0),smoothstep(3400.0,9000.0,temp*g));
  color*=mix(vec3(1.0),vec3(1.10,1.03,.92),smoothstep(.65,1.8,texture));
  float hotSheet=smoothstep(1.05,2.35,texture);
  color+=vec3(1.0,.86,.66)*uLuminosity*emissivity*hotSheet*.075;
  float opacity=1.0-exp(-uOpacity*taper*(.61+.39*texture)*sqrt(uDiskThickness)/max(abs(local.y),.16));
  return vec4(color,opacity);
}
vec3 palette(float x){return .5+.5*cos(6.28318*(vec3(.0,.32,.64)+x));}
void main(){
  vec2 xy=(vUv-vec2(uCenter,.51))*vec2(uResolution.x/uResolution.y,1.0);
  vec3 ray=normalize(uForward+tan(radians(uFov)*.5)*2.0*(uRight*xy.x+uUp*xy.y));
  vec3 observer=uCamera/uHoleScale;
  float r0=length(observer), f0=max(.001,1.0-1.0/r0);
  vec3 er=observer/r0;
  float mu=dot(ray,er), tangent=sqrt(max(1.0-mu*mu,1e-12));
  vec3 et=normalize(ray-er*mu);
  float impact=r0*tangent/sqrt(f0);
  vec2 s=vec2(1.0/r0,-mu/max(impact,1e-6));
  float orbitConstant=1.0/(impact*impact);
  float phi=0.0,transmittance=1.0, crossings=0.0, gSeen=1.0, gravSeen=1.0, tempSeen=0.0, beamSeen=1.0,error=0.0, steps=0.0;
  bool captured=false, escaped=false;
  vec3 emission=vec3(0.0), skyDirection=ray;
  float nextCross=atan(-er.y,et.y);
  if(nextCross<.00001) nextCross+=PI;
  if(impact<.001 && mu<0.0) captured=true;
  for(int i=0;i<1024;i++){
    if(i>=uMaxSteps || captured || escaped) break;
    // Adaptive phi step bounds fractional radial change, while resolving near-critical orbits.
    float h=min(uStep,.17*max(s.x,.015)/max(abs(s.y),.025));
    h=max(h,.00008);
    vec2 sn=rk4(s,h);
    float newPhi=phi+h;
    if(newPhi>=nextCross){
      vec2 sc=rk4(s,nextCross-phi);
      float rc=1.0/max(sc.x,1e-8);
      if(sc.x>0.0 && rc>=uInner && rc<=uOuter){
        vec3 radial=er*cos(nextCross)+et*sin(nextCross);
        vec3 angular=-er*sin(nextCross)+et*cos(nextCross);
        vec3 direction=normalize(-sc.y*radial+sc.x*angular);
        float g,grav,temp,beam;
        vec4 sampleColor=disk(radial*rc,direction,f0,g,grav,temp,beam);
        float windingBoost=nextCross>PI?uPhotonRing:1.0;
        emission+=transmittance*sampleColor.rgb*sampleColor.a*windingBoost;
        transmittance*=1.0-sampleColor.a;
        if(crossings<.5){gSeen=g;gravSeen=grav;tempSeen=temp;beamSeen=beam;}
        crossings+=1.0;
      }
      nextCross+=PI;
    }
    // Finite Gaussian atmosphere around the equatorial emitting sheet.
    // The analytic crossing above resolves the bright core even at grazing angles.
    if(sn.x>0.0&&sn.x<1.0){
      float rr=1.0/sn.x;
      vec3 pp=(er*cos(newPhi)+et*sin(newPhi))*rr;
      float height=.022*uDiskThickness*pow(rr,1.2);
      if(rr>=uInner&&rr<=uOuter&&abs(pp.y)<height*2.5){
        float gg,gr,tt,bb;
        vec3 tangentDir=normalize(-sn.y*normalize(pp)+sn.x*(-er*sin(newPhi)+et*cos(newPhi)));
        vec4 fog=disk(pp,tangentDir,f0,gg,gr,tt,bb);
        float ds=h*sqrt(sn.y*sn.y+sn.x*sn.x)/(sn.x*sn.x);
        float a=1.0-exp(-.052*fog.a*exp(-.5*pp.y*pp.y/(height*height))*ds/max(height,.001));
        emission+=transmittance*fog.rgb*a;transmittance*=1.0-a;
      }
    }
    steps+=1.0;
    error=max(error,abs(sn.y*sn.y+sn.x*sn.x-uLensing*sn.x*sn.x*sn.x-orbitConstant)/max(orbitConstant,.00001));
    if(sn.x>=1.0){captured=true;}
    if(sn.x<=0.0){
      float a=clamp(s.x/(s.x-sn.x),0.0,1.0);
      float escapePhi=phi+h*a;
      skyDirection=normalize(er*cos(escapePhi)+et*sin(escapePhi));
      newPhi=escapePhi;escaped=true;
    }
    s=sn;phi=newPhi;
  }
  // Exhausted near-critical rays are classified explicitly in diagnostics 1 and 10 (magenta).
  vec3 background=escaped?sky(skyDirection):vec3(0.0);
  vec3 color=emission+transmittance*background;
  if(uDebug==1)color=(!captured&&!escaped)?vec3(1,0,1):palette(phi/(2.0*PI))*(captured?.15:1.0);
  if(uDebug==2)color=crossings<.5?vec3(.006):thermal(tempSeen);
  if(uDebug==3)color=crossings<.5?vec3(.006):mix(vec3(1.0,.09,.015),vec3(.1,.4,1),smoothstep(.5,1.7,beamSeen));
  if(uDebug==4)color=crossings<.5?vec3(.006):palette(gravSeen*.7)*.8;
  if(uDebug==5)color=phi>2.0*PI?emission*1.5:vec3(.0);
  if(uDebug==6)color=background;
  if(uDebug==7)color=emission;
  if(uDebug==8){float critical=1.5*sqrt(3.0);color=vec3(.035)*floor(impact)+vec3(.9,.35,.05)*exp(-pow((impact-critical)/.022,2.0));}
  if(uDebug==10)color=captured?vec3(0):escaped?vec3(.42,.57,.66):vec3(1,0,1);
  if(uDebug==11)color=crossings<.5?vec3(.006):palette(crossings*.18)*min(crossings*.4+.2,1.0);
  if(uDebug==12)color=mix(vec3(.005,.12,.06),vec3(1,.02,.0),clamp((log2(max(error,1e-10))+24.0)/18.0,0.0,1.0));
  gl_FragColor=vec4(max(color,vec3(0.0)),1.0);
}
`;

export const downsample = `
precision highp float;
varying vec2 vUv;
uniform sampler2D uInput;
uniform vec2 uTexel;
uniform float uThreshold;
void main(){
  vec3 c=texture2D(uInput,vUv).rgb*4.0;
  c+=texture2D(uInput,vUv+uTexel*vec2(-1,-1)).rgb;
  c+=texture2D(uInput,vUv+uTexel*vec2(1,-1)).rgb;
  c+=texture2D(uInput,vUv+uTexel*vec2(-1,1)).rgb;
  c+=texture2D(uInput,vUv+uTexel*vec2(1,1)).rgb;c*=.125;
  float brightness=max(max(c.r,c.g),c.b);
  c*=max(brightness-uThreshold,0.0)/max(brightness,.0001);
  gl_FragColor=vec4(c,1.0);
}
`;
export const blur = `
precision highp float;
varying vec2 vUv;
uniform sampler2D uInput;
uniform vec2 uDirection;
void main(){
  vec3 c=texture2D(uInput,vUv).rgb*.227027;
  c+=(texture2D(uInput,vUv+uDirection*1.384615).rgb+texture2D(uInput,vUv-uDirection*1.384615).rgb)*.316216;
  c+=(texture2D(uInput,vUv+uDirection*3.230769).rgb+texture2D(uInput,vUv-uDirection*3.230769).rgb)*.070270;
  gl_FragColor=vec4(c,1.0);
}
`;
export const composite = `
precision highp float;
varying vec2 vUv;
uniform sampler2D uScene,uBloom0,uBloom1,uBloom2,uBloom3;
uniform vec2 uResolution;
uniform float uBloom,uExposure,uVignette,uGrain,uChromatic,uTime,uCenter;
uniform int uDebug;
vec3 aces(vec3 x){return clamp((x*(2.51*x+.03))/(x*(2.43*x+.59)+.14),0.0,1.0);}
float rand(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233))+uTime*1.73)*43758.5453);}
void main(){
  vec2 shift=(vUv-.5)*uChromatic/uResolution;
  vec3 color=texture2D(uScene,vUv).rgb;
  if(uDebug==0){
    color.r=texture2D(uScene,vUv+shift).r;
    color.b=texture2D(uScene,vUv-shift).b;
    vec3 bloom=texture2D(uBloom0,vUv).rgb*.36+texture2D(uBloom1,vUv).rgb*.28+texture2D(uBloom2,vUv).rgb*.22+texture2D(uBloom3,vUv).rgb*.14;
    color+=bloom*uBloom;
    color=aces(color*uExposure);
    vec2 p=(vUv-vec2(uCenter,.51))*vec2(1.1,1.0);
    color*=1.0-uVignette*smoothstep(.2,.86,length(p));
    color=pow(color,vec3(1.0/2.2));
    color+=(rand(gl_FragCoord.xy)-.5)*uGrain*.035*smoothstep(.005,.12,dot(color,vec3(.2126,.7152,.0722)));
  }else{if(uDebug==9)color=texture2D(uBloom0,vUv).rgb*.36+texture2D(uBloom1,vUv).rgb*.28+texture2D(uBloom2,vUv).rgb*.22+texture2D(uBloom3,vUv).rgb*.14;color=pow(aces(color),vec3(1.0/2.2));}
  gl_FragColor=vec4(max(color,vec3(0.0)),1.0);
}
`;
